DROP TABLE IF EXISTS `notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `notification` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL,
  `title` varchar(128) NOT NULL,
  `content` varchar(512) DEFAULT NULL,
  `category` varchar(24) DEFAULT '预警',
  `level` varchar(12) DEFAULT 'info' COMMENT 'info/warn/alert',
  `channel` varchar(12) NOT NULL DEFAULT 'INBOX' COMMENT 'INBOX/SMS/WECOM',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0未读 1已读',
  `link` varchar(128) DEFAULT NULL,
  `escalated` tinyint(4) NOT NULL DEFAULT '0',
  `read_at` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_status` (`user_id`,`status`),
  KEY `idx_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='通知中心';
