INSERT INTO `notification` VALUES (1,1,'质检不合格：LW-2026-A08-01','A-08 东坡八号农残检测不合格，已暂停采收，请尽快处置。','质检不合格','alert','INBOX',0,'/alerts',0,NULL,'2026-11-01 21:04:19'),(2,1,'冷链温度超限：SH20261027010','皖A·3F279 途中温度 9.1℃，超出 2–8℃ 区间。','冷链异常','warn','SMS',0,'/alerts',0,NULL,'2026-11-01 23:19:19'),(3,1,'超时升级：质检不合格未处理','A-08 预警超过 2 小时仍待处理，已升级至合作社管理员。','超时升级','alert','WECOM',0,'/alerts',1,NULL,'2026-11-01 23:54:19'),(4,1,'订单已结算：SO20261030-003','南京众彩果品批发行订单完成结算，金额已入账。','销售订单','info','INBOX',1,'/sale',0,'2026-11-02 00:04:19','2026-11-01 00:04:19'),(5,1,'今日采收已入库','三个基地今日共采收 4,080 kg，已分别入 1 号保鲜库与 2 号冷藏库。','仓储','info','INBOX',1,'/warehouse',0,'2026-11-02 00:04:19','2026-11-01 23:24:19');
