DROP TABLE IF EXISTS `plot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `plot` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `farm_id` bigint(20) NOT NULL,
  `plot_no` varchar(32) NOT NULL COMMENT 'A-01',
  `name` varchar(64) NOT NULL,
  `area_mu` decimal(10,2) NOT NULL,
  `soil_type` varchar(32) DEFAULT NULL,
  `center_lng` decimal(10,7) NOT NULL,
  `center_lat` decimal(10,7) NOT NULL,
  `polygon_json` json NOT NULL COMMENT 'GeoJSON Polygon: [[[lng,lat],...]]',
  `crop_id` bigint(20) DEFAULT NULL,
  `current_batch_id` bigint(20) DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1生长中 2待采收 3休耕 4预警',
  `manager_id` bigint(20) DEFAULT NULL,
  `del_flag` tinyint(4) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plot` (`farm_id`,`plot_no`),
  KEY `idx_batch` (`current_batch_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='地块';
/*!40101 SET character_set_client = @saved_cs_client */;

