DROP TABLE IF EXISTS `production_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `production_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `batch_id` bigint(20) NOT NULL,
  `type` varchar(16) NOT NULL COMMENT '播种/施肥/打药/灌溉/除草/采收',
  `input_item_id` bigint(20) DEFAULT NULL,
  `dosage` decimal(10,2) DEFAULT NULL,
  `unit` varchar(16) DEFAULT NULL,
  `quantity_kg` decimal(10,2) DEFAULT NULL COMMENT '采收/测产重量',
  `operator_id` bigint(20) DEFAULT NULL,
  `happen_time` datetime NOT NULL,
  `photo_json` json DEFAULT NULL,
  `remark` varchar(255) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_batch_time` (`batch_id`,`happen_time`),
  KEY `idx_type_time` (`type`,`happen_time`)
) ENGINE=InnoDB AUTO_INCREMENT=21008 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
